var t=[{title:`Bases de la pompe`,text:`Placez les mains là où vous êtes à l’aise, gardez le corps en une seule ligne des épaules aux hanches, descendez avec les coudes à un angle que vos épaules tolèrent et repoussez le sol. Vos omoplates se déplacent naturellement autour de la cage thoracique pendant une pompe. Ne laissez pas les hanches s’affaisser ni la tête avancer juste pour compter une répétition.`},{title:`Choisir une variante`,text:`Une pompe contre le mur est souvent la plus facile. Vient ensuite une pompe inclinée sur un plan de travail ou un banc solide, puis une pompe sur les genoux ou au sol complète. Plus tard, vous pouvez surélever les pieds ou ajouter une charge pour la rendre plus difficile. Savoir si la version sur les genoux ou la version inclinée est plus facile pour vous dépend du levier et du confort. Surélever les mains est un moyen simple de pousser moins de poids du corps.`},{title:`Développés couché et aux haltères`,text:`Sur un banc, plantez fermement les pieds, installez une position stable du tronc et des épaules et descendez les poids sous contrôle. Une barre fixe vos mains en place, tandis que les haltères laissent la prise bouger plus librement mais demandent du contrôle de chaque côté. Les tentatives de développé couché lourd nécessitent un pareur compétent ou un équipement de sécurité adapté.`},{title:`Malentendus courants`,text:`Vos coudes n’ont pas à rester collés aux côtes, et ils ne doivent pas non plus toujours s’écarter à l’horizontale. Choisissez une largeur de prise et une trajectoire des coudes qui vous permettent de bouger avec force et confort. Vos omoplates ne restent pas figées dans une seule position dans tous les développés, et les pompes au sol et les développés couché leur demandent des choses différentes.`},{title:`Avec TrainUp`,text:`Gardez une seule variante de pompe et notez ses répétitions jusqu’à ce que vous soyez prêt à passer à la suivante. Au fil de la semaine, équilibrez la poussée horizontale avec du travail de tirage. Si vos poignets ou vos épaules sont sensibles, ajoutez-les comme limites dans Profil pour que votre programme ne choisisse que des poussées adaptées.`}];var o=[{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Clinique Mayo : technique de musculation (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA : sécurité et fondamentaux du renforcement`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var n={sections:t,sources:o};export{n as default,t as sections,o as sources};